#include "SplatLODTestSupport.h"
#include "Renderer/Splat/Streaming/SplatGPUPagePool.h"
#include "Renderer/Splat/LOD/SplatLODBuilder.h"
#include "Renderer/Splat/LOD/SplatSceneFormat.h"
#include <algorithm>
#include <numeric>
#include <cmath>
#include "SplatLODPoolExtraTests.h"
#include "SplatLODRound3GPUTests.h"
#include "SplatTightCullingTests.h"
#include "SplatRadixSortTests.h"
using namespace SplatVerification;
int main(int argc,char** argv){if(argc>1&&std::string(argv[1])=="--radix-benchmark"){try{return RunRadixMicrobenchmark(argc,argv);}catch(const std::exception& e){std::cerr<<"MICROBENCHMARK FAIL "<<e.what()<<char(10);return 1;}}fs::create_directories("TestFile/3DGSLODStreaming/verification/logs");InitializeLogging((ArtifactRoot()/"logs/gpu-engine.log").string().c_str(),false,true,ELogVerbosity::Warning);Suite suite;
    try{Device d;
        suite.Test("T09 real completion tokens reject zero future recording",[&]{Require(!d.rhi->isSubmissionComplete({0}),"zero completed");auto previous=d.rhi->getLastSubmissionToken();Require(!d.rhi->isSubmissionComplete({previous.value+100}),"unknown future completed");auto c=d.Begin();Require(d.rhi->getLastSubmissionToken().value==previous.value,"recording minted token");c->writeGPUTimestamp(901,"FormalEmpty",true);c->writeGPUTimestamp(901,"FormalEmpty",false);auto token=d.Submit(c);Require(token.value>previous.value,"token did not increase");Require(d.rhi->supportsGPUTimestamps(),"ENV: hardware timestamps unavailable");auto samples=d.rhi->pollGPUTimestamps();Require(std::any_of(samples.begin(),samples.end(),[](const auto& s){return s.frame==901&&s.label=="FormalEmpty"&&std::isfinite(s.milliseconds)&&s.milliseconds>=0;}),"hardware timestamp absent after real fence");});
        for(unsigned n:{1u,2u,255u,256u,257u,1025u})suite.Test("T11 actual GPU inclusive scan tail N="+std::to_string(n),[&d,n]{FSplatPrefixSumPass scan;Require(scan.initialize(d.rhi,n),"scan init");std::vector<unsigned> input(n),oracle(n);for(unsigned i=0;i<n;++i)input[i]=(i%7)+1;std::partial_sum(input.begin(),input.end(),oracle.begin());auto upload=Buffer(d.rhi,n*4,EMemoryUsage::Upload,input.data());auto c=d.Begin();c->copyBuffer(scan.getBufferA(),upload,n*4);c->resourceBarrier();scan.execute(c,n);d.Submit(c);Require(d.ReadBuffer<unsigned>(scan.getResultBuffer(),n)==oracle,"inclusive scan differs from CPU oracle including nonzero tail");});
        for(unsigned keyBits:{48u,64u})for(unsigned n:{0u,1u,255u,257u,8193u,1048579u})suite.Test("T12 stable radix sort bits="+std::to_string(keyBits)+" N="+std::to_string(n),[&d,n,keyBits]{FSplatRadixSortPass sort;Require(sort.initialize(d.rhi,std::max(n,1u)),"radix init");std::vector<uint64_t> keys(std::max(n,1u));std::vector<unsigned> values(std::max(n,1u));std::vector<std::pair<uint64_t,unsigned>> oracle;for(unsigned i=0;i<n;++i){keys[i]=(uint64_t((n-i)%5)<<32)|((i%13)*0x1020304ull);values[i]=i;oracle.emplace_back(keys[i],i);}std::stable_sort(oracle.begin(),oracle.end(),[](auto a,auto b){return a.first<b.first;});auto ku=Buffer(d.rhi,keys.size()*8,EMemoryUsage::Upload,keys.data()),vu=Buffer(d.rhi,values.size()*4,EMemoryUsage::Upload,values.data());FSplatTileBoundariesPass boundary;Require(boundary.initialize(d.rhi,8,std::max(n,1u)),"boundary init");auto c=d.Begin();c->copyBuffer(sort.getKeysEven(),ku,keys.size()*8);c->copyBuffer(sort.getValuesEven(),vu,values.size()*4);c->resourceBarrier();sort.execute(c,n,keyBits);c->resourceBarrier();boundary.setSortedKeys(sort.getSortedKeys());boundary.execute(c,n);d.Submit(c);auto actualKeys=d.ReadBuffer<uint64_t>(sort.getSortedKeys(),std::max(n,1u));auto actualValues=d.ReadBuffer<unsigned>(sort.getSortedValues(),std::max(n,1u));for(unsigned i=0;i<n;++i)Require(actualKeys[i]==oracle[i].first&&actualValues[i]==oracle[i].second,"64bit sort stability/oracle mismatch");auto ranges=d.ReadBuffer<unsigned>(boundary.getTileRanges(),16);for(unsigned tile=0;tile<8;++tile){unsigned lo=0,hi=0;for(unsigned i=0;i<n;++i)if((oracle[i].first>>32)==tile){if(!hi)lo=i;hi=i+1;}Require(ranges[tile*2]==lo&&ranges[tile*2+1]==hi,"tile range CPU oracle mismatch");}});
        suite.Test("T10 compact source indexing and source SH stride",[&]{auto g=Source(d);FSplatPreprocessPass p;Require(p.initialize(d.rhi,3),"preprocess init");p.setInputs(g);p.updateCamera(Camera(0));Require(p.setActiveIndices({2,0},true),"active remap rejected");auto c=d.Begin();Require(p.execute(c,2),"preprocess execute");d.Submit(c);auto depths=d.ReadBuffer<float>(p.getOutput().depth,2),colors=d.ReadBuffer<float>(p.getOutput().rgb,8);Require(std::abs(depths[0]-5)<1e-5&&std::abs(depths[1]-3)<1e-5,"sourceIdx versus compactIdx mismatch");constexpr float dc=.28209479177387814f;Require(std::abs(colors[0]-(.5f+dc))<1e-4&&std::abs(colors[4]-(.5f-dc))<1e-4,"source degree1 stride incorrectly uses display degree0 stride");Require(!p.setActiveIndices({3},true),"out-of-range source index accepted");});
        suite.Test("T13 physical pipeline budget rejects impossible explicit capacities",[&]{FSplatPipeline p;p.SetCapacityBudgets(3,1000000,64000000,512ull<<20);Require(!p.initialize(d.rhi,3,1920,1080),"impossible temporary allocation accepted");});
        suite.Test("T10 T13 overflow retains prior image and zero active clears",[&]{auto g=Source(d);FSplatPipeline p;p.SetCapacityBudgets(3,3,4,16ull<<20);Require(p.initialize(d.rhi,3,64,64),"bounded pipeline init");p.setGaussianData(g);p.setCamera(Camera());FSplatActiveSet active;active.sourceIndices={0};p.SetActiveSet(active);FSplatLODRuntimeOptions o;o.benchmark=true;o.captureOnly=true;o.width=o.height=64;o.sequencePath="registered-synthetic-fixture";o.captureTimes={0,1,2};o.outputDirectory=Directory("gpu-captures").string();o.streaming.temporaryGPUBytes=32ull<<20;FSplatLODBenchmark recorder;std::string e;Require(recorder.Begin(o,{},e),e);
            auto capture=[&](double time){auto c=d.Begin();auto image=p.execute(c);Require(bool(image),"pipeline output missing");Require(recorder.RecordCapture(d.rhi,c,image,p.GetFrameStats().frame,time,Camera(),p.GetFrameStats().temporaryBytes,e),e);auto token=d.Submit(c);p.MarkFrameSubmitted(token);Require(recorder.FinishCapture(token,e),e);return Read(fs::path(o.outputDirectory)/(std::string("capture_00")+char('0'+int(time))+".rgba"));};
            // A small valid splat touches four center tiles; three overlap > capacity.
            auto first=capture(0);auto stats=p.CollectCompletedFrameStats();Require(!stats.countSamples.empty()&&!stats.countSamples.back().overflow,"first valid fixture unexpectedly overflowed");Require(std::any_of(first.begin(),first.end(),[](uint8_t x){return x!=0;}),"valid output transparent");active.sourceIndices={0,1,2};++active.selectionVersion;p.SetActiveSet(active);auto overflow=capture(1);stats=p.CollectCompletedFrameStats();Require(!stats.countSamples.empty()&&stats.countSamples.back().overflow,"deliberate overflow not reported");Require(first==overflow,"overflow changed prior valid image");active.sourceIndices.clear();++active.selectionVersion;p.SetActiveSet(active);auto zero=capture(2);stats=p.CollectCompletedFrameStats();Require(!stats.countSamples.empty()&&stats.countSamples.back().count==0&&!stats.countSamples.back().overflow,"same-frame zero count not measured");Require(std::all_of(zero.begin(),zero.end(),[](uint8_t x){return x==0;}),"zero active retained stale pixels");Require(recorder.Finish(true,"formal capture fixture",e),e);});
        suite.Test("T09 real pool physical caps readiness lease and stale generation",[&]{auto dir=Directory("pool-fixture");FSplatGaussian g;g.position[2]=-5;g.scale[0]=g.scale[1]=g.scale[2]=.1f;FSplatLODBuildConfig build;build.sourceSHA256=std::string(64,'a');build.builderHash=std::string(64,'b');FSplatSceneManifest m;std::string e;FSplatLODBuilder builder;Require(builder.Build({g},0,build,(dir/"scene").string(),m,e),e);FSplatStreamingConfig cfg;cfg.sceneGPUBytes=4096;cfg.stagingBytes=512;cfg.maxUploadBytesPerFrame=512;FSplatGPUPagePool pool;Require(pool.Initialize(d.rhi,m,cfg,e),e);auto allocated=pool.GetAllocationStats();Require(allocated.sourceReservedBytes>0&&allocated.sourceReservedBytes==allocated.sourceBackingBytes&&allocated.sourceReservedBytes<=cfg.sceneGPUBytes&&allocated.stagingBackingBytes<=cfg.stagingBytes,"physical pool caps/accounting");auto result=[&](unsigned gen){FSplatPageResult r;r.pageId=0;r.sceneGeneration=gen;r.bytes=Read(dir/"scene"/m.pages[0].relativePath);Require(FSplatSceneFormat::DecodePage(m,0,r.bytes,r.decodedGaussians,e),e);return r;};FSplatLODSelection selection;selection.selectedNodeIds={0};selection.desiredNodeIds={0};selection.requestPageIds={0};pool.ProtectSelection(selection);Require(pool.TryQueueUpload(result(1),e),e);Require(pool.GetPendingCPUBytes()>0,"queued CPU ownership uncharged");auto c=d.Begin();pool.Tick(c,1);Require(!pool.GetResidency().IsPageReady(0),"recorded upload prematurely ready");auto old=d.rhi->getLastSubmissionToken();pool.MarkFrameSubmitted(old);Require(!pool.GetResidency().IsPageReady(0),"unchanged submit token published ready");auto token=d.Submit(c);pool.MarkFrameSubmitted(token);c=d.Begin();pool.Tick(c,1);d.Submit(c);Require(pool.GetResidency().IsPageReady(0),"completed upload not ready");auto active=pool.BuildActiveSet(selection);Require(active.sourceIndices.size()==1,"ready pool mapping missing");auto releases=pool.DrainReleasedTransfers();Require(releases==std::vector<std::pair<uint32_t,uint64_t>>{{0,1}}&&pool.GetPendingCPUBytes()==0,"CPU transfer release closure");auto stale=result(0);Require(!pool.TryQueueUpload(std::move(stale),e),"stale generation accepted");pool.Shutdown();Require(pool.GetStats().residentBytes==0,"pool shutdown residency leak");});
        suite.Test("T12 generic 64bit sort retains nonzero top bytes and stable ties",[&]{
            constexpr unsigned n=16385;FSplatRadixSortPass sort;Require(sort.initialize(d.rhi,n),"full-key radix init");
            std::vector<uint64_t> keys(n);std::vector<unsigned> values(n);std::vector<std::pair<uint64_t,unsigned>> oracle;
            for(unsigned i=0;i<n;++i){keys[i]=(uint64_t(i%37)<<56)|(uint64_t((i%11)*17)<<40)|uint64_t(i%19);values[i]=i;oracle.emplace_back(keys[i],i);}
            std::stable_sort(oracle.begin(),oracle.end(),[](auto a,auto b){return a.first<b.first;});
            auto ku=Buffer(d.rhi,n*8,EMemoryUsage::Upload,keys.data()),vu=Buffer(d.rhi,n*4,EMemoryUsage::Upload,values.data());
            auto c=d.Begin();c->copyBuffer(sort.getKeysEven(),ku,n*8);c->copyBuffer(sort.getValuesEven(),vu,n*4);c->resourceBarrier();
            Require(sort.execute(c,n,64),"full 64bit execute");d.Submit(c);
            auto actualKeys=d.ReadBuffer<uint64_t>(sort.getSortedKeys(),n);auto actualValues=d.ReadBuffer<unsigned>(sort.getSortedValues(),n);
            for(unsigned i=0;i<n;++i)Require(actualKeys[i]==oracle[i].first&&actualValues[i]==oracle[i].second,"top byte or stable tie ordering lost");
        });
        RunPoolExtra(suite,d);
        RunRound3GPU(suite,d);
        RunTightCullingTests(suite,d); RunRadixSortTests(suite,d);
    }catch(const std::exception& e){suite.Test("ENV real Vulkan prerequisites",[&]{throw std::runtime_error(e.what());});}
    int result=suite.Finish();ShutdownLogging();return result;
}
